using System.Security.Claims;
using System.Text;
using Microsoft.AspNetCore.Authorization;
using Microsoft.AspNetCore.Identity;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using WudilFood.Data;
using WudilFood.Models;
namespace WudilFood.Controllers;

[Authorize(Roles=Roles.Admin)]
public class AdminController(AppDb db,UserManager<AppUser> userManager):Controller
{
 string Uid=>User.FindFirstValue(ClaimTypes.NameIdentifier)!;
 void Audit(string action,string entityType,object entityId,string details)=>db.AuditLogs.Add(new AuditLog{ActorId=Uid,Action=action,EntityType=entityType,EntityId=entityId.ToString()??"",Details=details});

 public async Task<IActionResult> Index()
 {
  await EnsureAdminSchema();
  var allOrders=db.Orders.AsNoTracking();ViewBag.Orders=await allOrders.CountAsync();ViewBag.Revenue=await allOrders.Where(x=>x.State==OrderState.Completed).SumAsync(x=>(decimal?)(x.ItemsTotal+x.DeliveryFee))??0;ViewBag.Vendors=await db.Vendors.CountAsync(x=>x.Status==ApprovalStatus.Approved);ViewBag.PendingVendors=await db.Vendors.CountAsync(x=>x.Status==ApprovalStatus.Pending);ViewBag.OpenComplaints=await db.Complaints.CountAsync(x=>x.Resolution=="");ViewBag.Cancelled=await allOrders.CountAsync(x=>x.State==OrderState.Cancelled);
  var salesLines=await db.OrderLines.AsNoTracking().Select(x=>new{x.ItemName,x.Quantity,x.UnitPrice}).ToListAsync();
  ViewBag.Popular=salesLines.GroupBy(x=>x.ItemName).Select(g=>new AdminProductStat(g.Key,g.Sum(x=>x.Quantity),g.Sum(x=>x.Quantity*x.UnitPrice))).OrderByDescending(x=>x.Quantity).Take(5).ToList();
  ViewBag.RecentOrders=await db.Orders.AsNoTracking().Include(x=>x.Vendor).Include(x=>x.Customer).OrderByDescending(x=>x.CreatedUtc).Take(8).ToListAsync();ViewBag.PendingList=await db.Vendors.AsNoTracking().Include(x=>x.User).Where(x=>x.Status==ApprovalStatus.Pending).OrderBy(x=>x.Id).Take(6).ToListAsync();ViewBag.RecentAudit=await db.AuditLogs.AsNoTracking().OrderByDescending(x=>x.CreatedUtc).Take(6).ToListAsync();
  return View();
 }

 public async Task<IActionResult> Orders(string? q,int? vendorId,OrderState? state,PaymentState? payment,DateOnly? from,DateOnly? to){var orders=db.Orders.AsNoTracking().Include(x=>x.Vendor).Include(x=>x.Customer).AsQueryable();if(!string.IsNullOrWhiteSpace(q))orders=orders.Where(x=>EF.Functions.ILike(x.Reference,"%"+q+"%")||EF.Functions.ILike(x.Customer.FullName,"%"+q+"%"));if(vendorId.HasValue)orders=orders.Where(x=>x.VendorId==vendorId);if(state.HasValue)orders=orders.Where(x=>x.State==state);if(payment.HasValue)orders=orders.Where(x=>x.PaymentState==payment);if(from.HasValue){var start=from.Value.ToDateTime(TimeOnly.MinValue,DateTimeKind.Local).ToUniversalTime();orders=orders.Where(x=>x.CreatedUtc>=start);}if(to.HasValue){var end=to.Value.AddDays(1).ToDateTime(TimeOnly.MinValue,DateTimeKind.Local).ToUniversalTime();orders=orders.Where(x=>x.CreatedUtc<end);}ViewBag.Vendors=await db.Vendors.AsNoTracking().OrderBy(x=>x.Name).ToListAsync();ViewBag.Query=q;ViewBag.VendorId=vendorId;ViewBag.State=state;ViewBag.Payment=payment;ViewBag.From=from;ViewBag.To=to;return View(await orders.OrderByDescending(x=>x.CreatedUtc).Take(100).ToListAsync());}
 public async Task<IActionResult> Vendors(){ViewBag.Pending=await db.Vendors.CountAsync(x=>x.Status==ApprovalStatus.Pending);return View(await db.Vendors.AsNoTracking().Include(x=>x.User).Include(x=>x.Items).OrderBy(x=>x.Status).ThenBy(x=>x.Name).ToListAsync());}
 public async Task<IActionResult> Moderation(){ViewBag.Reviews=await db.Reviews.AsNoTracking().Include(x=>x.Order).ThenInclude(x=>x.Vendor).Where(x=>!x.Approved).OrderByDescending(x=>x.Id).Take(50).ToListAsync();ViewBag.Complaints=await db.Complaints.AsNoTracking().Include(x=>x.Order).ThenInclude(x=>x.Vendor).OrderBy(x=>x.Resolution!="").ThenByDescending(x=>x.CreatedUtc).Take(50).ToListAsync();return View();}
 public async Task<IActionResult> Users(){ViewBag.Vendors=await userManager.GetUsersInRoleAsync(Roles.Vendor);return View(await userManager.GetUsersInRoleAsync(Roles.Customer));}
 public async Task<IActionResult> Riders()=>View(await db.Riders.AsNoTracking().OrderByDescending(x=>x.IsActive).ThenBy(x=>x.Name).ToListAsync());
 public async Task<IActionResult> Configuration(){ViewBag.Categories=await db.Categories.AsNoTracking().OrderBy(x=>x.Name).ToListAsync();return View(await db.Settings.AsNoTracking().FirstAsync());}
 public async Task<IActionResult> Activity(){await EnsureAdminSchema();return View(await db.AuditLogs.AsNoTracking().OrderByDescending(x=>x.CreatedUtc).Take(200).ToListAsync());}

 async Task EnsureAdminSchema()=>await db.Database.ExecuteSqlRawAsync("""
 CREATE TABLE IF NOT EXISTS "AuditLogs" (
   "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
   "ActorId" character varying(80) NOT NULL,
   "Action" character varying(80) NOT NULL,
   "EntityType" character varying(80) NOT NULL,
   "EntityId" character varying(80) NOT NULL,
   "Details" character varying(500) NOT NULL,
   "CreatedUtc" timestamp with time zone NOT NULL
 );
 CREATE INDEX IF NOT EXISTS "IX_AuditLogs_CreatedUtc" ON "AuditLogs" ("CreatedUtc" DESC);
 """);

 [HttpGet]public async Task<IActionResult> ExportOrders(string? q,int? vendorId,OrderState? state,PaymentState? payment,DateOnly? from,DateOnly? to){var orders=db.Orders.AsNoTracking().Include(x=>x.Vendor).Include(x=>x.Customer).AsQueryable();if(!string.IsNullOrWhiteSpace(q))orders=orders.Where(x=>EF.Functions.ILike(x.Reference,"%"+q+"%")||EF.Functions.ILike(x.Customer.FullName,"%"+q+"%"));if(vendorId.HasValue)orders=orders.Where(x=>x.VendorId==vendorId);if(state.HasValue)orders=orders.Where(x=>x.State==state);if(payment.HasValue)orders=orders.Where(x=>x.PaymentState==payment);if(from.HasValue){var start=from.Value.ToDateTime(TimeOnly.MinValue,DateTimeKind.Local).ToUniversalTime();orders=orders.Where(x=>x.CreatedUtc>=start);}if(to.HasValue){var end=to.Value.AddDays(1).ToDateTime(TimeOnly.MinValue,DateTimeKind.Local).ToUniversalTime();orders=orders.Where(x=>x.CreatedUtc<end);}var rows=await orders.OrderByDescending(x=>x.CreatedUtc).Take(5000).ToListAsync();var csv=new StringBuilder("Reference,Vendor,Customer,Created,Slot,Fulfilment,Status,Payment,Total\r\n");foreach(var o in rows)csv.AppendLine(string.Join(',',new[]{Csv(o.Reference),Csv(o.Vendor.Name),Csv(o.Customer.FullName),Csv(o.CreatedUtc.ToString("O")),Csv(o.SlotUtc.ToString("O")),Csv(o.Fulfillment.ToString()),Csv(o.State.ToString()),Csv(o.PaymentState.ToString()),o.Total.ToString("0.00",System.Globalization.CultureInfo.InvariantCulture)}));return File(Encoding.UTF8.GetPreamble().Concat(Encoding.UTF8.GetBytes(csv.ToString())).ToArray(),"text/csv",$"wudil-orders-{DateTime.UtcNow:yyyyMMdd}.csv");}
 static string Csv(string value)=>$"\"{value.Replace("\"","\"\"")}\"";

 [HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> VendorStatus(int id,ApprovalStatus status,string reason){if(!Enum.IsDefined(status)||string.IsNullOrWhiteSpace(reason)||reason.Length>300)return BadRequest();var v=await db.Vendors.FindAsync(id);if(v==null)return NotFound();var old=v.Status;v.Status=status;var message=$"Your vendor account changed from {old} to {status}. Reason: {reason.Trim()}";db.Notices.Add(new Notice{UserId=v.UserId,Text=message});Audit("Vendor status changed","Vendor",id,message);await db.SaveChangesAsync();return RedirectToAction(nameof(Vendors));}
 [HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> AccountStatus(string id,bool active,string reason){if(string.IsNullOrWhiteSpace(reason)||reason.Length>300)return BadRequest();var user=await userManager.FindByIdAsync(id);if(user==null||await userManager.IsInRoleAsync(user,Roles.Admin))return NotFound();user.LockoutEnabled=true;user.LockoutEnd=active?null:DateTimeOffset.UtcNow.AddYears(100);var result=await userManager.UpdateAsync(user);if(!result.Succeeded)return BadRequest(string.Join("; ",result.Errors.Select(x=>x.Description)));Audit(active?"Account reactivated":"Account suspended","User",id,reason.Trim());await db.SaveChangesAsync();return RedirectToAction(nameof(Users));}
 [HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> SaveRider(int id,string name,string phoneNumber){if(string.IsNullOrWhiteSpace(name)||name.Length>100||string.IsNullOrWhiteSpace(phoneNumber)||phoneNumber.Length>30||phoneNumber.Count(char.IsDigit)<7)return BadRequest("Enter a valid rider name and phone number.");var rider=id==0?new Rider():await db.Riders.FindAsync(id);if(rider==null)return NotFound();rider.Name=name.Trim();rider.PhoneNumber=phoneNumber.Trim();if(id==0)db.Riders.Add(rider);Audit(id==0?"Rider created":"Rider updated","Rider",id==0?"new":id,$"{rider.Name} · {rider.PhoneNumber}");await db.SaveChangesAsync();return RedirectToAction(nameof(Riders));}
 [HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> RiderStatus(int id){var rider=await db.Riders.FindAsync(id);if(rider==null)return NotFound();rider.IsActive=!rider.IsActive;Audit(rider.IsActive?"Rider activated":"Rider deactivated","Rider",id,rider.Name);await db.SaveChangesAsync();return RedirectToAction(nameof(Riders));}
 [HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Payment(int id,PaymentState status){if(!Enum.IsDefined(status))return BadRequest();var o=await db.Orders.FindAsync(id);if(o==null)return NotFound();var old=o.PaymentState;o.PaymentState=status;db.Notices.Add(new Notice{UserId=o.CustomerId,Text=$"Payment for {o.Reference}: {status}."});Audit("Payment status changed","Order",id,$"{old} to {status}");await db.SaveChangesAsync();return RedirectToAction("Details","Orders",new{id});}
 [HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Moderate(int id,bool approved,string? reason){var r=await db.Reviews.Include(x=>x.Order).FirstOrDefaultAsync(x=>x.Id==id);if(r==null)return NotFound();if(approved)r.Approved=true;else db.Reviews.Remove(r);Audit(approved?"Review approved":"Review rejected","Review",id,reason?.Trim()??"");await db.SaveChangesAsync();return RedirectToAction(nameof(Moderation));}
 [HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Resolve(int id,string resolution){var c=await db.Complaints.Include(x=>x.Order).FirstOrDefaultAsync(x=>x.Id==id);if(c==null||string.IsNullOrWhiteSpace(resolution)||resolution.Length>1000)return BadRequest();c.Resolution=resolution.Trim();db.Notices.Add(new Notice{UserId=c.UserId,Text=$"Complaint for {c.Order.Reference} resolved: {c.Resolution}"});Audit("Complaint resolved","Complaint",id,c.Resolution);await db.SaveChangesAsync();return RedirectToAction(nameof(Moderation));}
 [HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Category(string name){if(string.IsNullOrWhiteSpace(name)||name.Length>80)return BadRequest();db.Categories.Add(new Category{Name=name.Trim()});Audit("Category created","Category","new",name.Trim());await db.SaveChangesAsync();return RedirectToAction(nameof(Configuration));}
 [HttpPost,ValidateAntiForgeryToken]public async Task<IActionResult> Settings(decimal deliveryFee,string coverage,bool deliveryEnabled){if(deliveryFee<0||deliveryFee>100000||string.IsNullOrWhiteSpace(coverage)||coverage.Length>500)return BadRequest();var s=await db.Settings.FirstAsync();s.DeliveryFee=deliveryFee;s.Coverage=coverage.Trim();s.DeliveryEnabled=deliveryEnabled;Audit("Platform settings updated","PlatformSetting",s.Id,$"Fee {deliveryFee}; coverage {coverage}; delivery {deliveryEnabled}");await db.SaveChangesAsync();return RedirectToAction(nameof(Configuration));}
}
public record AdminProductStat(string Name,int Quantity,decimal Revenue);
